(* [comment removed for export] *)

Definition COND_BROADCAST_STACK : Z := 80.

Definition cond_broadcast_stmt : Prop :=
  forall (C clk lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APCond m C clk ->
  (C + 48 <= 0x10000 \/ 0x67f000 <= C) ->
  ACanaryReads m ->
  stk asegs m lo (bv_unsigned sp) -> lo + COND_BROADCAST_STACK <= bv_unsigned sp -> aceil <= lo ->
  (C + 48 <= lo \/ bv_unsigned sp <= C) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m ->
  evt asegs (privsig_post ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc C clk lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_PTHREAD_COND_BROADCAST) fc None m (seg_rom asegs)).

Lemma cond_broadcast_spec : cond_broadcast_stmt.
Proof.
  intros until m; intros PC OFF CAN ST LO HC SEP RA MI. unfold COND_BROADCAST_STACK in LO.
  destruct (PCond_cells _ _ _ PC) as (PCC & CK & AL).
  pose proof (rw_cells_bound _ _ _ _ PCC) as B. cbn [cells_size csize Nat.add length] in B.
  init_fp [(lo, bv_unsigned sp); (C, C + 48)]%Z.
  unfold P_A_PTHREAD_COND_BROADCAST in *. change (wz C) with (Z_to_bv 64 C).
  (* [comment removed for export] *)
  step. step. if_true. step. step.
  pose proof privsig_spec as PS. unfold privsig_stmt, privsig_stmt_at, P_A_PRIVATE_COND_SIGNAL, PRIVSIG_STACK in PS.
  eapply evt_mono; [eapply (PS C clk lo); try eassumption |].
  - vm_compute. discriminate.
  - cbv beta. intros ms' PO. unfold privsig_post in *.
    destruct PO as (x1 & x2 & x3 & x4 & x5 & x6 & m' & -> & MU' & WM' & MI' & ST' & PC' & CAN').
    eexists _, _, _, _, _, _, _. split; [reflexivity|].
    split; [eapply munch_trans; [exact MU| exact MU']|].
    split; [eapply wmono_trans; [exact WM| exact WM']|].
    split; [exact MI'|]. split; [exact ST'|]. split; [exact PC'| exact CAN'].
Qed.

